import java.io.*;
import java.util.*;

public class F {

	long[][] ways;

	static class Half implements Comparable<Half> {
		long match;
		long value;

		public Half(long match, long value) {
			this.match = match;
			this.value = value;
		}

		@Override
		public int compareTo(Half o) {
			return Long.compare(value, o.value);
		}
	}

	boolean nextCombination(int[] a, int n) {
		int k = a.length;
		int ptr = k - 1;
		while (ptr >= 0 && a[ptr] == ptr - k + n) {
			ptr--;
		}
		if (ptr < 0) {
			return false;
		}
		a[ptr]++;
		for (int i = ptr + 1; i < k; i++) {
			a[i] = a[ptr] + i - ptr;
		}
		return true;
	}

	long getWins(char[] s, int r, int c) {
		int countA = 0, countB = 0;
		long totalWins = 0;
		for (char ch : s) {
			if (ch == 'A') {
				countA++;
			} else {
				totalWins += choose(countB, r - 1) * choose(countA, r);
				countB++;
			}
		}
		return totalWins;
	}

	long slow(int r, int c, String s) {
		int[] positions = new int[r + c];
		for (int i = 0; i < r + c; i++) {
			positions[i] = i;
		}
		long totalWays = ways[r + c][r] * ways[r + c][c];

		char[] buffer = new char[2 * (r + c)];
		long minDiff = Long.MAX_VALUE;
		long totalMatches = 0;

		List<String> bestConfigs = new ArrayList<>();

		do {
			Arrays.fill(buffer, 'B');
			for (int pos : positions) {
				buffer[pos] = 'A';
			}
			int matchFlag = 1;
			for (int i = 0; i < buffer.length; i++) {
				if (s.charAt(i) != '?' && s.charAt(i) != buffer[i]) {
					matchFlag = 0;
					break;
				}
			}
			long winsA = getWins(buffer, r, c);
			long diff = Math.abs(2 * winsA - totalWays);
			if (diff < minDiff) {
				minDiff = diff;
				bestConfigs.clear();
				if (matchFlag == 1) {
					bestConfigs.add(new String(buffer));
				}
				totalMatches = matchFlag;
			} else if (diff == minDiff) {
				totalMatches += matchFlag;
				if (matchFlag == 1) {
					bestConfigs.add(new String(buffer));
				}
			}
		} while (nextCombination(positions, 2 * (r + c)));
		return totalMatches;
	}

	long solve(int r, int c, String s) {
		long currentBestDiff = Long.MAX_VALUE;
		long totalAnswer = 0;

		long maskA = 0, maskB = 0;
		int[][] prefixCount = new int[s.length() + 1][2];
		for (int i = 0; i < s.length(); i++) {
			prefixCount[i + 1] = prefixCount[i].clone();
			if (s.charAt(i) == 'A') {
				prefixCount[i + 1][0]++;
				maskA |= 1L << i;
			}
			if (s.charAt(i) == 'B') {
				prefixCount[i + 1][1]++;
				maskB |= 1L << i;
			}
		}

		long lastA = maskA >> (2 * r + c - 1);
		long lastB = maskB >> (2 * r + c - 1);

		Half[][] firstHalf = new Half[c + 2][];
		Half[][] secondHalf = new Half[c + 2][];
		int[] sizeArr = new int[c + 2];

		for (int i = 0; i < c + 2; i++) {
			sizeArr[i] = (int) ways[c + 1][i];
			firstHalf[i] = new Half[sizeArr[i]];
			secondHalf[i] = new Half[sizeArr[i]];
		}

		for (int mask = 0; mask < (1 << (c + 1)); mask++) {
			int bitsCount = Integer.bitCount(mask);
			int complementBits = c + 1 - bitsCount;
			int index = --sizeArr[bitsCount];

			int samePrefixCount = Math.min(Integer.numberOfTrailingZeros((mask & 1) == 0 ? mask : (mask + 1)), c + 1);
			int totalA = r - 1 - prefixCount[2 * r - 2 + samePrefixCount][0];
			int totalB = r - 1 - prefixCount[2 * r - 2 + samePrefixCount][1];

			if ((mask & 1) == 0) {
				totalA += samePrefixCount;
			} else {
				totalB += samePrefixCount;
			}

			long winsA = 0;
			int countA = 0, countB = 0;
			for (int i = 0; i < c + 1; i++) {
				if (test(mask, i)) {
					winsA += ways[r - 1 + countB][r - 1] * choose(r - 1 + countA, r);
					countB++;
				} else {
					countA++;
				}
			}

			int exactMatchFlag = 1;
			for (int i = samePrefixCount; i < c + 1; i++) {
				if ((!test(mask, i) && s.charAt(2 * r - 2 + i) == 'B') ||
					(test(mask, i) && s.charAt(2 * r - 2 + i) == 'A')) {
					exactMatchFlag = 0;
					break;
				}
			}

			firstHalf[bitsCount][index] = new Half(choose(totalA + totalB, totalA) * exactMatchFlag, winsA);

			int matchFlag = 1;
			if (((~mask) & lastB) != 0 || (mask & lastA) != 0) {
				matchFlag = 0;
			}
			long winsA2 = 0;
			int curA2 = bitsCount, curB2 = complementBits;
			for (int i = 0; i < c + 1; i++) {
				if (test(mask, i)) {
					winsA2 += ways[r - 1 + curB2][r - 1] * choose(r - 1 + curA2, r);
					curB2++;
				} else {
					curA2++;
				}
			}
			secondHalf[bitsCount][index] = new Half(matchFlag, winsA2);
		}

		long totalWaysVal = ways[r + c][r] * ways[r + c][r];
		long halfTotal = totalWaysVal / 2;

		for (int i = 0; i <= c + 1; i++) {
			Half[] listOne = compress(firstHalf[i]);
			Half[] listTwo = compress(secondHalf[c + 1 - i]);
			int pointer = listTwo.length - 1;
			for (Half a : listOne) {
				while (pointer >= 0 && a.value + listTwo[pointer].value > halfTotal) {
					pointer--;
				}
				if (pointer >= 0) {
					update(a, listTwo[pointer], totalWaysVal);
				}
				if (pointer + 1 < listTwo.length) {
					update(a, listTwo[pointer + 1], totalWaysVal);
				}
			}
		}
		return totalAnswer;
	}

	void submit() {
		int r = nextInt();
		int c = nextInt();
		String s = nextToken();
		out.println(solve(r, c, s));
	}

	long totalWays;

	long bestDiff = Long.MAX_VALUE;
	long ans = 0;

	void update(Half a, Half b, long totalWaysVal) {
		long totalVal = a.value + b.value;
		long diff = Math.abs(2 * totalVal - totalWaysVal);
		long delta = a.match * b.match;
		if (diff < bestDiff) {
			bestDiff = diff;
			ans = delta;
		} else if (diff == bestDiff) {
			ans += delta;
		}
	}

	Half[] compress(Half[] arr) {
		Arrays.sort(arr);
		int sz = 1;
		for (int i = 1; i < arr.length; i++) {
			if (arr[i].value == arr[sz - 1].value) {
				arr[sz - 1].match += arr[i].match;
			} else {
				arr[sz++] = arr[i];
			}
		}
		return Arrays.copyOf(arr, sz);
	}

	long choose(int n, int k) {
		return n >= 0 && k >= 0 && k <= n ? ways[n][k] : 0;
	}

	static boolean test(int mask, int i) {
		return ((mask >> i) & 1) == 1;
	}

	void preCalc() {
		ways = new long[61][];
		for (int i = 0; i < ways.length; i++) {
			ways[i] = new long[i + 1];
			ways[i][0] = ways[i][i] = 1;
			for (int j = 1; j < i; j++) {
				ways[i][j] = ways[i - 1][j - 1] + ways[i - 1][j];
			}
		}
	}

	void stress() {
		for (int tst = 0;; tst++) {
			int r = rand(1, 3);
			int c = rand(1, 3);
			char[] buf = new char[2 * (r + c)];
			Arrays.fill(buf, '?');
			String s = new String(buf);
			long fast = solve(r, c, s);
			long slow = slow(r, c, s);
			if (fast != slow) {
				System.err.println(r + " " + c + " " + s);
				System.err.println(fast);
				System.err.println(slow);
				throw new AssertionError();
			}
			System.err.println(tst + " passed");
		}
	}

	void test() {
		int r = 1;
		int c = 3;
		String s = "ABBAABBA";
		System.err.println(solve(r, c, s));
	}

	F() throws IOException {
		br = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);
		preCalc();
		submit();
		out.close();
	}

	static final Random rng = new Random();

	static int rand(int l, int r) {
		return l + rng.nextInt(r - l + 1);
	}

	public static void main(String[] args) throws IOException {
		new F();
	}

	BufferedReader br;
	PrintWriter out;
	StringTokenizer st;

	String nextToken() {
		while (st == null || !st.hasMoreTokens()) {
			try {
				st = new StringTokenizer(br.readLine());
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return st.nextToken();
	}

	String nextString() {
		try {
			return br.readLine();
		} catch (IOException e) {
			throw new RuntimeException(e);
		}
	}

	int nextInt() {
		return Integer.parseInt(nextToken());
	}

	long nextLong() {
		return Long.parseLong(nextToken());
	}

	double nextDouble() {
		return Double.parseDouble(nextToken());
	}
}
